local IronGateMaker = {}
local PRODUCTS = {
    simple_iron_gate = { name = "Preprosta železna vrata", ironCost = 4, woodCost = 2, time = 6, cost = 200, defense = 35, happiness = 1, description = "Preprosta železna vrata za obzidje." },
    riveted_reinforced_gate = { name = "Zakovučena ojačana vrata", ironCost = 4, steelCost = 2, woodCost = 2, time = 9, cost = 480, defense = 52, happiness = 2, prestige = 3, description = "Zakovučena ojačana vrata za trgovce." },
    silver_trimmed_gate = { name = "Srebrnoobrobljena vrata", ironCost = 4, silverCost = 2, steelCost = 1, woodCost = 2, time = 13, cost = 1100, defense = 68, happiness = 2, prestige = 8, description = "Srebrnoobrobljena vrata za plemiče." },
    gold_inlaid_gate = { name = "Zlatovložena vrata", ironCost = 4, goldCost = 2, silverCost = 1, steelCost = 1, woodCost = 2, time = 17, cost = 2500, defense = 82, happiness = 3, prestige = 18, description = "Zlatovložena vrata za visoke plemiče." },
    jewel_set_gate = { name = "Draguljasta vrata", ironCost = 4, goldCost = 2, silverCost = 1, steelCost = 1, woodCost = 2, jewelCost = 1, time = 21, cost = 5200, defense = 92, happiness = 5, prestige = 32, description = "Vrata z draguljem za visoko plemstvo." },
    royal_grand_gate = { name = "Kraljevski veliki vrata", ironCost = 6, goldCost = 3, silverCost = 2, steelCost = 2, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 28, cost = 11000, defense = 100, happiness = 13, prestige = 65, description = "Velika kraljevska vrata z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    gate_workshop = { name = "Vratna delavnica", cost = { gold = 320, wood = 140, stone = 160, iron = 8 }, upkeep = 7, qualityBonus = 5 },
    smithy_loft = { name = "Kovaška podstrešje", cost = { gold = 1100, wood = 280, stone = 320, steel = 6, silver = 6 }, upkeep = 26, qualityBonus = 18 },
    master_gatesmith_atelier = { name = "Mojstrski vratarski atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_gates_palace = { name = "Kraljevska vratarska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
IronGateMaker.ironStock = 18; IronGateMaker.steelStock = 10; IronGateMaker.woodStock = 14; IronGateMaker.silverStock = 8; IronGateMaker.goldStock = 6; IronGateMaker.jewelStock = 4; IronGateMaker.pearlStock = 4
IronGateMaker.productStock = {}; IronGateMaker.buildings = {}; IronGateMaker.maker = nil; IronGateMaker.activeMaking = {}; IronGateMaker.totalProducts = 0; IronGateMaker.dayTimer = 0
function IronGateMaker.init() IronGateMaker.ironStock=18; IronGateMaker.steelStock=10; IronGateMaker.woodStock=14; IronGateMaker.silverStock=8; IronGateMaker.goldStock=6; IronGateMaker.jewelStock=4; IronGateMaker.pearlStock=4; IronGateMaker.productStock={}; IronGateMaker.buildings={}; IronGateMaker.maker=nil; IronGateMaker.activeMaking={}; IronGateMaker.totalProducts=0; IronGateMaker.dayTimer=0; print("[IronGateMaker] Royal Iron Gate Maker System initialized (6 products, 4 buildings)") end
function IronGateMaker.hireMaker(n,s) s=s or math.random(55,90); local c=620+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; IronGateMaker.maker={name=n or (" vratar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vratar najet: %s (spretnost: %d)",IronGateMaker.maker.name,s),"success") end; return true end
function IronGateMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function IronGateMaker.build(id) local ok,e=IronGateMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(IronGateMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function IronGateMaker.getQualityBonus() local b=0; for _,bd in ipairs(IronGateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function IronGateMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and IronGateMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and IronGateMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and IronGateMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and IronGateMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and IronGateMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and IronGateMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and IronGateMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #IronGateMaker.buildings==0 then return false,"Potrebna vratna delavnica" end; if not IronGateMaker.maker then return false,"Potreben vratar" end; return true end
function IronGateMaker.make(pt,qty) qty=qty or 1; local ok,e=IronGateMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then IronGateMaker.ironStock=IronGateMaker.ironStock-d.ironCost*qty end; if d.steelCost then IronGateMaker.steelStock=IronGateMaker.steelStock-d.steelCost*qty end; if d.woodCost then IronGateMaker.woodStock=IronGateMaker.woodStock-d.woodCost*qty end; if d.silverCost then IronGateMaker.silverStock=IronGateMaker.silverStock-d.silverCost*qty end; if d.goldCost then IronGateMaker.goldStock=IronGateMaker.goldStock-d.goldCost*qty end; if d.jewelCost then IronGateMaker.jewelStock=IronGateMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then IronGateMaker.pearlStock=IronGateMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if IronGateMaker.maker then t=math.max(1,t-math.floor(IronGateMaker.maker.skill/12)) end; table.insert(IronGateMaker.activeMaking,{id="irongate_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function IronGateMaker.completeMaking(m) local q=1.0+(IronGateMaker.getQualityBonus()/100); if IronGateMaker.maker then q=q+(IronGateMaker.maker.skill/140) end; q=math.min(2.5,q); IronGateMaker.productStock[m.productType]=(IronGateMaker.productStock[m.productType] or 0)+m.quantity; IronGateMaker.totalProducts=IronGateMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if IronGateMaker.maker then IronGateMaker.maker.itemsMade=IronGateMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then IronGateMaker.maker.skill=math.min(100,IronGateMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrata izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"irongate.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function IronGateMaker.update(dt) if not _G.state then return end; IronGateMaker.dayTimer=IronGateMaker.dayTimer+dt; if IronGateMaker.dayTimer>=30 then IronGateMaker.dayTimer=0; for i=#IronGateMaker.activeMaking,1,-1 do local m=IronGateMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then IronGateMaker.completeMaking(m); table.remove(IronGateMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(IronGateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if IronGateMaker.maker then tu=tu+17 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function IronGateMaker.getStats() return {ironStock=IronGateMaker.ironStock,steelStock=IronGateMaker.steelStock,woodStock=IronGateMaker.woodStock,silverStock=IronGateMaker.silverStock,goldStock=IronGateMaker.goldStock,jewelStock=IronGateMaker.jewelStock,pearlStock=IronGateMaker.pearlStock,productStock=IronGateMaker.productStock,numBuildings=#IronGateMaker.buildings,hasMaker=IronGateMaker.maker~=nil,makerName=IronGateMaker.maker and IronGateMaker.maker.name or "—",makerSkill=IronGateMaker.maker and IronGateMaker.maker.skill or 0,activeMaking=#IronGateMaker.activeMaking,totalProducts=IronGateMaker.totalProducts} end
return IronGateMaker
